const fs = require("fs");
const ApiClient = require("./external-urcap-api/ApiClient").default;
const { URCapsApi } = require("./external-urcap-api");
const sshTunnelHelper = require("./ssh-tunnel-helper");
const { log } = sshTunnelHelper;

class UrcapInstallationError extends Error {
  constructor(message, details, statusCode) {
    super(message);
    this.details = details;
    this.statusCode = statusCode;
  }
}

function getHost() {
  const args = process.argv.slice(2);
  let idx = args.indexOf("--host");
  let host = "localhost";
  if (process.env.DEV_CONTAINER === "true") {
    host = "host.docker.internal";
  }
  if (idx > -1 && args.length > idx + 1) {
    // User has specified a host
    host = args[idx + 1];
  }
  return host;
}

function createApiClient(basePath) {
  const apiClient = new ApiClient();
  apiClient.basePath = basePath;
  return new URCapsApi(apiClient);
}

function urcapExists(urcapsApi, vendorId, urcapId) {
  return new Promise((resolve, reject) => {
    urcapsApi.infoUrcap(vendorId, urcapId, (err, _res) => {
      if (err && err.status === 404) {
        resolve(false);
      } else if (err) {
        reject(
          new UrcapInstallationError(
            "Unable to reach URCap API",
            err.message || err.code,
            err.status || err.errno,
          ),
        );
      } else {
        resolve(true);
      }
    });
  });
}

function isLocalHost(host) {
  return (
    host === "localhost" ||
    host === "127.0.0.1" ||
    host === "host.docker.internal"
  );
}

function getPort() {
  const args = process.argv.slice(2);
  const idx = args.indexOf("--port");
  if (idx > -1 && args.length > idx + 1) {
    return args[idx + 1];
  }
  return "80";
}

async function withTunnel(fn) {
  const host = getHost();

  if (isLocalHost(host)) {
    const basePath = `http://${host}:${getPort()}/universal-robots/urcap-system-api/urcap-system-api/internal`;
    const urcapsApi = createApiClient(basePath);
    const result = await fn(urcapsApi);
    return { result, host };
  }

  const tunnel = await sshTunnelHelper.openTunnel(host);

  await sshTunnelHelper.offerKeySetup(host, tunnel.password);

  const basePath = `http://127.0.0.1:${tunnel.port}/universal-robots/urcap-system-api/urcap-system-api/internal`;
  const urcapsApi = createApiClient(basePath);

  try {
    log("Performing API operation...");
    const result = await fn(urcapsApi);
    log("API operation completed.");
    return { result, host };
  } finally {
    await tunnel.close();
    log("SSH tunnel closed.");
  }
}

async function deleteUrcap(vendorId, urcapId) {
  const { result } = await withTunnel(async (urcapsApi) => {
    const exists = await urcapExists(urcapsApi, vendorId, urcapId);

    if (!exists) {
      throw new UrcapInstallationError("URCap does not exist");
    }

    return await deleteUrcapViaApi(urcapsApi, vendorId, urcapId);
  });

  return result;
}

async function installOrUpdateUrcap(
  urcapxFile,
  vendorId,
  urcapId,
  forceReinstall = false,
) {
  const { result } = await withTunnel(async (urcapsApi) => {
    const exists = await urcapExists(urcapsApi, vendorId, urcapId);

    if (exists && forceReinstall) {
      await deleteUrcapViaApi(urcapsApi, vendorId, urcapId);
      return await installUrcapViaApi(urcapsApi, urcapxFile);
    } else if (exists) {
      return await updateUrcapViaApi(urcapsApi, urcapxFile);
    }
    return await installUrcapViaApi(urcapsApi, urcapxFile);
  });

  return result;
}

async function deleteUrcapViaApi(urcapsApi, vendorId, urcapId) {
  return new Promise((resolve, reject) => {
    urcapsApi.deleteGivenUrcap(vendorId, urcapId, (error) => {
      if (error) {
        reject(
          new UrcapInstallationError(
            "Unable to delete URCap",
            error.response.body.message,
            error.status,
          ),
        );
      } else {
        resolve("URCap successfully deleted");
      }
    });
  });
}

async function installUrcapViaApi(urcapsApi, filePath) {
  const fileStream = fs.createReadStream(filePath);

  return new Promise((resolve, reject) => {
    urcapsApi.installUrcap(fileStream, (error, msg) => {
      if (error) {
        reject(
          new UrcapInstallationError(
            "Unable to install URCap",
            error.response.body.message,
            error.status,
          ),
        );
      } else {
        resolve(JSON.parse(msg.message));
      }
    });
  });
}

async function updateUrcapViaApi(urcapsApi, filePath) {
  const fileStream = fs.createReadStream(filePath);

  return new Promise((resolve, reject) => {
    urcapsApi.updateUrcap(fileStream, (error, msg) => {
      if (error) {
        reject(
          new UrcapInstallationError(
            "Unable to update URCap",
            error.response.body.message,
            error.status,
          ),
        );
      } else {
        resolve(JSON.parse(msg.details));
      }
    });
  });
}

module.exports = { deleteUrcap, installOrUpdateUrcap };
